137	    /**
138	     * Loads {@link RoutesBuilder} from {@link Resource} using the given consumer to create a {@link RouteBuilder}
139	     * instance.
140	     *
141	     * @param  resource the resource to be loaded.
142	     * @param  consumer the function used to create a {@link RoutesBuilder}
143	     * @return          a {@link RoutesBuilder}
144	     */
145	    public static RouteBuilder loadRoutesBuilder(
146	            Resource resource, ThrowingBiConsumer<Reader, RouteBuilder, Exception> consumer) {
147	        return new RouteBuilder() {
148	            @Override
149	            public void configure() throws Exception {
150	                CamelContextAware.trySetCamelContext(resource, getContext());
151	
152	                try (Reader reader = resource.getReader()) {
153	                    consumer.accept(reader, this);
154	                }
155	            }
156	        };
157	    }
