212	    /**
213	     * To customize a given component / data format / language / service using Java lambda style. This is only intended
214	     * for low-code integrations where you have a minimal set of code and files, to make it easy and quick to
215	     * customize/configure components directly in a single {@link RouteBuilder} class.
216	     *
217	     * @param type the type such as a component FQN class name
218	     * @param code callback for customizing the component instance (if present)
219	     */
220	    public <T> void customize(Class<T> type, VoidFunction<T> code) throws Exception {
221	        ObjectHelper.notNull(type, "type", this);
222	        ObjectHelper.notNull(code, "code", this);
223	
224	        // custom may be stored directly in registry so lookup first here
225	        T obj = getContext().getRegistry().findSingleByType(type);
226	        // try component / dataformat / language
227	        if (obj == null && Component.class.isAssignableFrom(type)) {
228	            org.apache.camel.spi.annotations.Component ann
229	                    = type.getAnnotation(org.apache.camel.spi.annotations.Component.class);
230	            if (ann != null) {
231	                String name = ann.value();
232	                // just grab first scheme name if the component has scheme alias (eg http,https)
233	                if (name.contains(",")) {
234	                    name = StringHelper.before(name, ",");
235	                }
236	                // do not auto-start component as we need to configure it first
237	                obj = (T) getCamelContext().getComponent(name, true, false);
238	            }
239	            // NOTE: SubComponent class is not available at compilation time.
240	            if (obj != null && !type.getName().equals("org.apache.camel.component.stub.StubComponent") // NOSONAR
241	                    && "org.apache.camel.component.stub.StubComponent".equals(obj.getClass().getName())) { // NOSONAR
242	                // if we run in stub mode then we can't apply the configuration as we stubbed the actual component
243	                obj = null;
244	            }
245	        }
246	        if (obj == null && DataFormat.class.isAssignableFrom(type)) {
247	            // it's maybe a dataformat
248	            Dataformat ann
249	                    = type.getAnnotation(Dataformat.class);
250	            if (ann != null) {
251	                String name = ann.value();
252	                obj = (T) getCamelContext().resolveDataFormat(name);
253	            }
254	        }
255	        if (obj == null && Language.class.isAssignableFrom(type)) {
256	            // it's maybe a dataformat
257	            org.apache.camel.spi.annotations.Language ann
258	                    = type.getAnnotation(org.apache.camel.spi.annotations.Language.class);
259	            if (ann != null) {
260	                String name = ann.value();
261	                obj = (T) getCamelContext().resolveLanguage(name);
262	            }
263	        }
264	        // it may be a special service
265	        if (obj == null) {
266	            obj = getContext().hasService(type);
267	        }
268	        if (obj != null) {
269	            code.apply(obj);
270	        }
271	    }
