273	    /**
274	     * To customize a given component / data format / language / service using Java lambda style. This is only intended
275	     * for low-code integrations where you have a minimal set of code and files, to make it easy and quick to
276	     * customize/configure components directly in a single {@link RouteBuilder} class.
277	     *
278	     * @param name the name of the component / service
279	     * @param type the type such as a component FQN class name
280	     * @param code callback for customizing the component instance (if present)
281	     */
282	    public <T> void customize(String name, Class<T> type, VoidFunction<T> code) throws Exception {
283	        ObjectHelper.notNull(name, "name", this);
284	        ObjectHelper.notNull(type, "type", this);
285	        ObjectHelper.notNull(code, "code", this);
286	
287	        T obj = getContext().getRegistry().lookupByNameAndType(name, type);
288	        if (obj == null && Component.class.isAssignableFrom(type)) {
289	            // do not auto-start component as we need to configure it first
290	            obj = (T) getCamelContext().getComponent(name, true, false);
291	            // NOTE: SubComponent class is not available at compilation time.
292	            if (obj != null && !"stub".equals(name)
293	                    && "org.apache.camel.component.stub.StubComponent".equals(obj.getClass().getName())) { // NOSONAR
294	                // if we run in stub mode then we can't apply the configuration as we stubbed the actual component
295	                obj = null;
296	            }
297	        }
298	        if (obj == null && DataFormat.class.isAssignableFrom(type)) {
299	            obj = (T) getCamelContext().resolveDataFormat(name);
300	        }
301	        if (obj == null && Language.class.isAssignableFrom(type)) {
302	            obj = (T) getCamelContext().resolveLanguage(name);
303	        }
304	        if (obj != null) {
305	            code.apply(obj);
306	        }
307	    }
