595	    /**
596	     * Injects a property placeholder value with the given key converted to the given type.
597	     *
598	     * @param  key       the property key
599	     * @param  type      the type to convert the value as
600	     * @return           the value, or <tt>null</tt> if value is empty
601	     * @throws Exception is thrown if property with key not found or error converting to the given type.
602	     */
603	    public <T> T propertyInject(String key, Class<T> type) throws Exception {
604	        StringHelper.notEmpty(key, "key");
605	        ObjectHelper.notNull(type, "Class type");
606	
607	        // the properties component is mandatory
608	        PropertiesComponent pc = getContext().getPropertiesComponent();
609	        // resolve property
610	        Optional<String> value = pc.resolveProperty(key);
611	
612	        if (value.isPresent()) {
613	            return getContext().getTypeConverter().mandatoryConvertTo(type, value.get());
614	        } else {
615	            return null;
616	        }
617	    }
