786	        Set<String> answer = new LinkedHashSet<>();
787	
788	        // must configure routes before rests
789	        configureRoutes(context);
790	        configureRests(context);
791	
792	        // but populate rests before routes, as we want to turn rests into routes
793	        populateBeans();
794	        populateRests();
795	        populateTransformers();
796	        populateValidators();
797	        populateRouteTemplates();
798	
799	        // ensure routes are prepared before being populated
800	        for (RouteDefinition route : routeCollection.getRoutes()) {
801	            routeCollection.prepareRoute(route);
802	        }
803	
804	        // trigger update of the routes
805	        populateOrUpdateRoutes();
806	
807	        // trigger reloaded routes to be started if under supervising controller
808	        // as this requires to be done manually via the controller
809	        // the default route controller will auto-start routes when added to camel
810	        if (getContext().getRouteController() instanceof SupervisingRouteController src) {
811	            src.startRoutes(true);
812	        }
813	
814	        if (this instanceof OnCamelContextEvent onCamelContextEvent) {
815	            context.addLifecycleStrategy(LifecycleStrategySupport.adapt(onCamelContextEvent));
816	        }
817	
818	        for (RouteDefinition route : routeCollection.getRoutes()) {
819	            String id = route.getRouteId();
820	            answer.add(id);
821	        }
822	
823	        return answer;
824	    }
