1000	    protected void populateRests() throws Exception {
1001	        CamelContext camelContext = notNullCamelContext();
1002	        getRestCollection().setCamelContext(camelContext);
1003	
1004	        // setup rest configuration before adding the rests
1005	        if (restConfiguration != null) {
1006	            restConfiguration.asRestConfiguration(getContext(), camelContext.getRestConfiguration());
1007	        }
1008	
1009	        // cannot add rests as routes yet as we need to initialize this
1010	        // specially
1011	        camelContext.getCamelContextExtension().getContextPlugin(Model.class).addRestDefinitions(getRestCollection().getRests(),
1012	                false);
1013	
1014	        // convert rests api-doc into routes so they are routes for runtime
1015	        RestConfiguration config = camelContext.getRestConfiguration();
1016	
1017	        if (config.getApiContextPath() != null) {
1018	            // avoid adding rest-api multiple times, in case multiple
1019	            // RouteBuilder classes is added
1020	            // to the CamelContext, as we only want to setup rest-api once
1021	            // so we check all existing routes if they have rest-api route
1022	            // already added
1023	            boolean hasRestApi = false;
1024	            for (RouteDefinition route : camelContext.getCamelContextExtension().getContextPlugin(Model.class)
1025	                    .getRouteDefinitions()) {
1026	                FromDefinition from = route.getInput();
1027	                if (from.getEndpointUri() != null && from.getEndpointUri().startsWith("rest-api:")) {
1028	                    hasRestApi = true;
1029	                }
1030	            }
1031	            if (!hasRestApi) {
1032	                RouteDefinition route = RestDefinition.asRouteApiDefinition(camelContext, config);
1033	                log.debug("Adding routeId: {} as rest-api route", route.getId());
1034	                getRouteCollection().route(route);
1035	            }
1036	        }
1037	
1038	        // add rest as routes and have them prepared as well via
1039	        // routeCollection.route method
1040	        getRestCollection().getRests()
1041	                .forEach(rest -> rest.asRouteDefinition(getContext()).forEach(route -> getRouteCollection().route(route)));
1042	    }
