3634	    public void startRouteService(RouteService routeService, boolean addingRoutes) throws Exception {
3635	        lock.lock();
3636	        try {
3637	            startingRoutes(() -> {
3638	                // the route service could have been suspended, and if so then
3639	                // resume it instead
3640	                if (routeService.getStatus().isSuspended()) {
3641	                    resumeRouteService(routeService);
3642	                } else {
3643	                    // start the route service
3644	                    routeServices.put(routeService.getId(), routeService);
3645	                    // special situation if Camel is stopping and we do graceful shutdown, and process remainder
3646	                    // inflight messages, and they trigger a dynamic endpoint (toD) that calls a kamelet, then
3647	                    // we need to allow creating the kamelet route to be able to process the inflight message
3648	                    boolean stoppingDynamicKamelet = isStopping() && routeService.getRoute().isCreatedByKamelet();
3649	                    if (shouldStartRoutes() || stoppingDynamicKamelet) {
3650	                        final StartupStepRecorder startupStepRecorder = camelContextExtension.getStartupStepRecorder();
3651	                        StartupStep step
3652	                                = startupStepRecorder.beginStep(Route.class, routeService.getId(), "Start Route Services");
3653	                        // this method will log the routes being started
3654	                        internalRouteStartupManager.safelyStartRouteServices(this, true, true, true, false, addingRoutes,
3655	                                routeService);
3656	                        // start route services if it was configured to auto startup
3657	                        // and we are not adding routes
3658	                        boolean isAutoStartup = routeService.isAutoStartup();
3659	                        if (!addingRoutes || isAutoStartup) {
3660	                            // start the route since auto start is enabled or we are
3661	                            // starting a route (not adding new routes)
3662	                            routeService.start();
3663	                        }
3664	                        startupStepRecorder.endStep(step);
3665	                    }
3666	                }
3667	                return null;
3668	            });
3669	        } finally {
3670	            lock.unlock();
3671	        }
3672	    }
