3675	     * Resumes the given route service
3676	     */
3677	    protected void resumeRouteService(RouteService routeService) throws Exception {
3678	        lock.lock();
3679	        try {
3680	            // the route service could have been stopped, and if so then start it
3681	            // instead
3682	            if (!routeService.getStatus().isSuspended()) {
3683	                startRouteService(routeService, false);
3684	            } else {
3685	                // resume the route service
3686	                if (shouldStartRoutes()) {
3687	                    // this method will log the routes being started
3688	                    internalRouteStartupManager.safelyStartRouteServices(this, true, false, true, true, false, routeService);
3689	                    // must resume route service as well
3690	                    routeService.resume();
3691	                }
3692	            }
3693	        } finally {
3694	            lock.unlock();
3695	        }
3696	    }
