3709	    protected void logRouteState(Route route, String state, LoggingLevel loggingLevel, int level) {
3710	        lock.lock();
3711	        try {
3712	            CamelLogger logger = new CamelLogger(LOG, loggingLevel);
3713	            if (logger.shouldLog()) {
3714	                String pad = " ".repeat(level);
3715	                if (route.getConsumer() != null) {
3716	                    String id = route.getId();
3717	                    String uri = route.getEndpoint().getEndpointBaseUri();
3718	                    uri = URISupport.sanitizeUri(uri);
3719	                    String line = String.format("%s%s %s (%s)", pad, state, id, uri);
3720	                    logger.log(line);
3721	                } else {
3722	                    String id = route.getId();
3723	                    String line = String.format("%s%s %s", pad, state, id);
3724	                    logger.log(line);
3725	                }
3726	            }
3727	        } finally {
3728	            lock.unlock();
3729	        }
3730	    }
