304	        // now prepare the routes by starting its services before we start the
305	        // input
306	        for (Map.Entry<Integer, DefaultRouteStartupOrder> entry : inputs.entrySet()) {
307	            // defer starting inputs till later as we want to prepare the routes
308	            // by starting
309	            // all their processors and child services etc.
310	            // then later we open the floods to Camel by starting the inputs
311	            // what this does is to ensure Camel is more robust on starting
312	            // routes as all routes
313	            // will then be prepared in time before we start inputs which will
314	            // consume messages to be routed
315	            RouteService routeService = entry.getValue().getRouteService();
316	            StartupStep step = camelContext.getCamelContextExtension().getStartupStepRecorder().beginStep(Route.class,
317	                    routeService.getId(),
318	                    "Warump Route");
319	            try {
320	                LOG.debug("Warming up route id: {} having autoStartup={}", routeService.getId(), autoStartup);
321	                setupRoute.set(routeService.getRoute());
322	                // ensure we setup before warmup
323	                routeService.setUp();
324	                routeService.warmUp();
325	            } finally {
326	                setupRoute.remove();
327	                camelContext.getCamelContextExtension().getStartupStepRecorder().endStep(step);
328	            }
329	        }
330	    }
