97	    /**
98	     * Invoked whenever we should be polled
99	     */
100	    @Override
101	    public void run() {
102	        // avoid this thread to throw exceptions because the thread pool wont re-schedule a new thread
103	        try {
104	            // log starting
105	            if (LoggingLevel.ERROR == runLoggingLevel) {
106	                LOG.error("Scheduled task started on:   {}", this.getEndpoint());
107	            } else if (LoggingLevel.WARN == runLoggingLevel) {
108	                LOG.warn("Scheduled task started on:   {}", this.getEndpoint());
109	            } else if (LoggingLevel.INFO == runLoggingLevel) {
110	                LOG.info("Scheduled task started on:   {}", this.getEndpoint());
111	            } else if (LoggingLevel.DEBUG == runLoggingLevel) {
112	                LOG.debug("Scheduled task started on:   {}", this.getEndpoint());
113	            } else {
114	                LOG.trace("Scheduled task started on:   {}", this.getEndpoint());
115	            }
116	
117	            // execute scheduled task
118	            doRun();
119	
120	            // log completed
121	            if (LoggingLevel.ERROR == runLoggingLevel) {
122	                LOG.error("Scheduled task completed on: {}", this.getEndpoint());
123	            } else if (LoggingLevel.WARN == runLoggingLevel) {
124	                LOG.warn("Scheduled task completed on: {}", this.getEndpoint());
125	            } else if (LoggingLevel.INFO == runLoggingLevel) {
126	                LOG.info("Scheduled task completed on: {}", this.getEndpoint());
127	            } else if (LoggingLevel.DEBUG == runLoggingLevel) {
128	                LOG.debug("Scheduled task completed on: {}", this.getEndpoint());
129	            } else {
130	                LOG.trace("Scheduled task completed on: {}", this.getEndpoint());
131	            }
132	        } catch (Error e) {
133	            // need to log so there is visibility as otherwise the user may not see anything in logs
134	            LOG.error("Fatal error occurred during running scheduled task on: {}, due: {}.",
135	                    this.getEndpoint(), e.getMessage(), e);
136	            throw e;
137	        } catch (Throwable e) {
138	            LOG.error("Error occurred during running scheduled task on: {}, due: {}."
139	                      + " This exception is ignored and the task will run again on next poll.",
140	                    this.getEndpoint(), e.getMessage(), e);
141	        }
142	    }
143	
144	    private void doRun() {
145	        if (isSuspended()) {
146	            LOG.trace("Cannot start to poll: {} as its suspended", this.getEndpoint());
147	            return;
148	        }
149	
150	        // should we backoff if its enabled, and either the idle or error counter is > the threshold
151	        if (backoffMultiplier > 0
152	                // either idle or error threshold could be not in use, so check for that and use MAX_VALUE if not in use
153	                && idleCounter.longValue() >= (backoffIdleThreshold > 0 ? backoffIdleThreshold : Integer.MAX_VALUE)
154	                || errorCounter.longValue() >= (backoffErrorThreshold > 0 ? backoffErrorThreshold : Integer.MAX_VALUE)) {
155	            final int currentBackoffCounter = backoffCounter.incrementAndGet();
156	            if (currentBackoffCounter < backoffMultiplier) {
157	                // yes we should backoff
158	                if (idleCounter.intValue() > 0) {
159	                    LOG.debug("doRun() backoff due subsequent {} idles (backoff at {}/{})", idleCounter.longValue(),
160	                            backoffCounter.intValue(), backoffMultiplier);
161	                } else {
162	                    LOG.debug("doRun() backoff due subsequent {} errors (backoff at {}/{})", errorCounter.intValue(),
163	                            backoffCounter.intValue(), backoffMultiplier);
164	                }
165	                return;
166	            } else {
167	                // we are finished with backoff so reset counters
168	                idleCounter.set(0);
169	                errorCounter.set(0);
170	                backoffCounter.set(0);
171	                successCounter.set(0);
172	                LOG.trace("doRun() backoff finished, resetting counters.");
173	            }
174	        }
175	
176	        long count = counter.incrementAndGet();
177	        boolean stopFire = repeatCount > 0 && count > repeatCount;
178	        if (stopFire) {
179	            LOG.debug("Cancelling {} scheduler as repeat count limit reached after {} counts.", getEndpoint(), repeatCount);
180	            scheduler.unscheduleTask();
181	            return;
182	        }
183	
184	        int retryCounter = -1;
185	        boolean done = false;
186	        Throwable cause = null;
187	        int polledMessages = 0;
188	
189	        while (!done) {
190	            try {
191	                // eager assume we are done
192	                done = true;
193	                if (isPollAllowed()) {
194	
195	                    if (retryCounter == -1) {
196	                        LOG.trace("Starting to poll: {}", this.getEndpoint());
197	                    } else {
198	                        LOG.debug("Retrying attempt {} to poll: {}", retryCounter, this.getEndpoint());
199	                    }
200	
201	                    // mark we are polling which should also include the begin/poll/commit
202	                    pollingCounter.incrementAndGet();
203	                    try {
204	                        boolean begin = pollStrategy.begin(this, getEndpoint());
205	                        if (begin) {
206	                            retryCounter++;
207	                            polledMessages = poll();
208	                            LOG.trace("Polled {} messages", polledMessages);
209	
210	                            if (polledMessages == 0 && isSendEmptyMessageWhenIdle()) {
211	                                // send an "empty" exchange
212	                                processEmptyMessage();
213	                            }
214	
215	                            pollStrategy.commit(this, getEndpoint(), polledMessages);
216	
217	                            if (polledMessages > 0 && isGreedy()) {
218	                                done = false;
219	                                retryCounter = -1;
220	                                LOG.trace("Greedy polling after processing {} messages", polledMessages);
221	
222	                                // clear any error that might be since we have successfully polled, otherwise readiness checks might believe the
223	                                // consumer to be unhealthy
224	                                errorCounter.set(0);
225	                                lastError = null;
226	                                lastErrorDetails = null;
227	
228	                                // setting firstPollDone to true if greedy polling is enabled
229	                                firstPollDone = true;
230	                            }
231	                        } else {
232	                            LOG.debug("Cannot begin polling as pollStrategy returned false: {}", pollStrategy);
233	                        }
234	                    } finally {
235	                        pollingCounter.decrementAndGet();
236	                    }
237	                }
238	
239	                LOG.trace("Finished polling: {}", this.getEndpoint());
240	            } catch (Exception e) {
241	                try {
242	                    boolean retry = pollStrategy.rollback(this, getEndpoint(), retryCounter, e);
243	                    if (retry) {
244	                        // do not set cause as we retry
245	                        done = false;
246	                    } else {
247	                        cause = e;
248	                        done = true;
249	                    }
250	                } catch (Exception t) {

