638	    protected void doStart() throws Exception {
639	        super.doStart();
640	
641	        boolean newScheduler = false;
642	        if (scheduler == null) {
643	            DefaultScheduledPollConsumerScheduler scheduler
644	                    = new DefaultScheduledPollConsumerScheduler(scheduledExecutorService);
645	            scheduler.setDelay(delay);
646	            scheduler.setInitialDelay(initialDelay);
647	            scheduler.setTimeUnit(timeUnit);
648	            scheduler.setUseFixedDelay(useFixedDelay);
649	            this.scheduler = scheduler;
650	            newScheduler = true;
651	        }
652	        ObjectHelper.notNull(scheduler, "scheduler", this);
653	        scheduler.setCamelContext(getEndpoint().getCamelContext());
654	
655	        // configure scheduler with options from this consumer
656	        if (schedulerProperties != null && !schedulerProperties.isEmpty()) {
657	            // need to use a copy in case the consumer is restarted so we keep the properties
658	            Map<String, Object> copy = new LinkedHashMap<>(schedulerProperties);
659	            PropertyBindingSupport.build().bind(getEndpoint().getCamelContext(), scheduler, copy);
660	            // special for trigger and job parameters
661	            Map<String, Object> triggerParameters = PropertiesHelper.extractProperties(copy, "trigger.");
662	            Map<String, Object> jobParameters = PropertiesHelper.extractProperties(copy, "job.");
663	            PropertyBindingSupport.build().bind(getEndpoint().getCamelContext(), scheduler, "triggerParameters",
664	                    triggerParameters);
665	            PropertyBindingSupport.build().bind(getEndpoint().getCamelContext(), scheduler, "jobParameters", jobParameters);
666	            if (!copy.isEmpty()) {
667	                throw new FailedToCreateConsumerException(
668	                        getEndpoint(), "There are " + copy.size()
669	                                       + " scheduler parameters that couldn't be set on the endpoint."
670	                                       + " Check the uri if the parameters are spelt correctly and that they are properties of the endpoint."
671	                                       + " Unknown parameters=[" + copy + "]");
672	            }
673	        }
674	        afterConfigureScheduler(scheduler, newScheduler);
675	
676	        scheduler.onInit(this);
677	
678	        if (scheduler != null) {
679	            scheduler.scheduleTask(this);
680	            ServiceHelper.startService(scheduler);
681	
682	            if (isStartScheduler()) {
683	                startScheduler();
684	            }
685	        }
686	    }
